import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { registerAllBlocks } from "@/engine/blocks";
import { allManifests } from "@/engine/registry";
import { moduleAbiFromManifests } from "@/engine/moduleContractSurface";

registerAllBlocks();
const abi = moduleAbiFromManifests(allManifests());
const target = join(process.cwd(), "src/engine/generatedModuleAbi.ts");
const source = `/**
 * GENERATED by scripts/generate-module-abi.ts. Do not edit by hand.
 * This compact projection keeps provider runners out of operator-page runtime.
 * Regenerate after changing executable module manifests.
 */
import type { ModuleAbiIndex } from "./moduleContractSurface";

export const GENERATED_MODULE_ABI: ModuleAbiIndex = ${JSON.stringify(abi, null, 2)};
`;
writeFileSync(target, source, "utf8");
console.log(`generated ABI surfaces for ${Object.keys(abi.modules).length} executable modules`);
